"""A-share taxes: a seller-side stamp duty that halved in 2023, and a dividend tax that
charges you for turnover.

WHY this exists: almost every A-share backtest prices costs as a flat symmetric number --
"10 bps a side" -- and the two taxes that actually apply are neither flat nor symmetric.

  STAMP DUTY (证券交易印花税) is levied on the SELLER ONLY. 印花税法 Article 3, verbatim:
  "证券交易印花税对证券交易的出让方征收，不对受让方征收。" A buy pays zero. And the rate
  HALVED on 2023-08-28, so a constant rate is wrong on one side of that date whichever
  number you pick.

  DIVIDEND TAX (股息红利个人所得税) is a STEP FUNCTION OF HOLDING PERIOD: exempt over one
  year, an effective 10% from one month to one year, an effective 20% at one month or less.
  A dividend-capture strategy and a buy-and-hold strategy collect the same cash and keep
  different amounts of it. That is a turnover penalty written into the tax code, and no
  A-share backtester models it.

Usage:
    from ashare_taxes import stamp_duty, dividend_tax_rate, compare_cost_models
    stamp_duty(1_000_000, side="S", date="2023-08-28")   -> 500.0
    stamp_duty(1_000_000, side="B", date="2023-08-28")   -> 0.0

These are MODELLING assumptions for a backtest, not tax advice, and the rules below are for
an INDIVIDUAL resident investor. Institutions, funds, QFII/RQFII and Stock Connect
investors are all treated differently and none of that is here. Check current law with a
professional before relying on any of it.

SOURCES (read 2026-09-09):
  中华人民共和国印花税法 (in force from 2022-07-01), fgk.chinatax.gov.cn/zcfgk/c100009/
    c5193058/content.html -- Article 3 defines 证券交易 as the transfer of shares and
    share-based depositary receipts traded on a lawfully established exchange, and levies
    the duty on the transferor only; the attached 印花税税目税率表 sets the rate at 1 per
    mille of the transaction amount (成交金额).
  财政部 税务总局公告2023年第39号《关于减半征收证券交易印花税的公告》, issued 2023-08-27,
    fgk.chinatax.gov.cn/zcfgk/c102416/c5211343/content.html -- "为活跃资本市场、提振投资者
    信心，自2023年8月28日起，证券交易印花税实施减半征收。" 1 per mille x 50% = 0.05%.
  财政部 news release 2008-09-19, mof.gov.cn/zhengwuxinxi/caizhengxinwen/200809/
    t20080919_76432.htm -- "调整为单边征税，即对买卖、继承、赠与所书立的A股、B股股权转让书据
    的出让方按千分之一的税率征收证券（股票）交易印花税，对受让方不再征税。" The document
    number is reported elsewhere as 财税明电〔2008〕2号; that number is secondhand.
  财税〔2015〕101号《财政部 国家税务总局 证监会关于上市公司股息红利差别化个人所得税政策有关
    问题的通知》, issued 2015-09-07, effective 2015-09-08,
    chinatax.gov.cn/n810341/n810755/c1797427/content.html -- >1 year exempt; <=1 month full
    inclusion at 20%; >1 month to <=1 year 50% inclusion at 20%. Withholding is deferred:
    the company withholds nothing at payment and 中国结算 computes it when the shares are
    sold. Article 4 (the NEEQ paragraph) was repealed by 公告2019年第78号; the dividend rules
    above remain in force and were applied by reference again in 公告2026年第8号 (2026-01-14).
"""
from __future__ import annotations

import numpy as np
import pandas as pd

# Dated rate table. Each row: effective from, rate, sides charged, and the authority.
# This library verified the regime from 2008-09-19 onward and states nothing before it.
STAMP_DUTY_HISTORY = (
    ("2008-09-19", 0.0010, ("S",), "MOF release 2008-09-19 (seller side only, 1 per mille)"),
    ("2022-07-01", 0.0010, ("S",), "Stamp Tax Law art. 3 + rate table (1 per mille, transferor)"),
    ("2023-08-28", 0.0005, ("S",), "MOF/STA Announcement 2023 No. 39 (halved from 2023-08-28)"),
)
EARLIEST_VERIFIED = pd.Timestamp("2008-09-19")

# 印花税法 art. 3: 证券交易 means transferring SHARES and share-based depositary receipts.
# Funds and ETFs are not shares, so a fund trade is outside the tax entirely.
DUTIABLE_INSTRUMENTS = ("stock", "a_share", "b_share", "cdr", "depositary_receipt")


def stamp_duty_rate(date, instrument: str = "stock") -> float:
    """Seller-side stamp duty rate in force on `date`. Zero for anything that is not a share."""
    d = pd.Timestamp(date)
    if d < EARLIEST_VERIFIED:
        raise ValueError(
            f"{d.date()} is before {EARLIEST_VERIFIED.date()}, the earliest date this library "
            f"verified. Before then the duty was levied on BOTH sides and the rate moved "
            f"several times (0.3% in 2007). Read the announcement for your period rather than "
            f"extrapolating this table backwards.")
    if instrument not in DUTIABLE_INSTRUMENTS:
        return 0.0
    rate = 0.0
    for start, r, _sides, _auth in STAMP_DUTY_HISTORY:
        if d >= pd.Timestamp(start):
            rate = r
    return rate


def stamp_duty(notional: float, side: str, date, instrument: str = "stock") -> float:
    """Stamp duty in currency. A BUY pays zero -- 印花税法 art. 3, transferor only."""
    s = str(side).upper()[0]
    if s not in ("B", "S"):
        raise ValueError("side must be 'B' (buy) or 'S' (sell)")
    if s == "B":
        return 0.0
    return abs(float(notional)) * stamp_duty_rate(date, instrument)


def rate_history_table() -> pd.DataFrame:
    return pd.DataFrame([{"from": s, "rate": r, "sides": "/".join(sd), "authority": a}
                         for s, r, sd, a in STAMP_DUTY_HISTORY])


# --------------------------------------------------------------------------- dividends
def holding_bucket(buy_date, sell_date) -> str:
    """财税〔2015〕101号: '<=1m', '1m-1y' or '>1y'. Calendar months, not 30 days.

    The boundaries are inclusive on the low side: 持股期限在1个月以内(含1个月) is the 20%
    bucket, and 1个月以上至1年(含1年) is the 10% bucket, so exactly one year is still taxed.
    """
    b, s = pd.Timestamp(buy_date), pd.Timestamp(sell_date)
    if s < b:
        raise ValueError("sell_date is before buy_date")
    if s <= b + pd.DateOffset(months=1):
        return "<=1m"
    if s <= b + pd.DateOffset(years=1):
        return "1m-1y"
    return ">1y"


# Effective rate = statutory 20% x the inclusion fraction in 财税〔2015〕101号.
DIVIDEND_EFFECTIVE_RATE = {"<=1m": 0.20, "1m-1y": 0.10, ">1y": 0.00}
DIVIDEND_INCLUSION = {"<=1m": 1.00, "1m-1y": 0.50, ">1y": 0.00}
DIVIDEND_RULE_FROM = pd.Timestamp("2015-09-08")


def dividend_tax_rate(buy_date, sell_date, record_date=None) -> float:
    """Effective personal income tax rate on an A-share dividend, by holding period."""
    if record_date is not None and pd.Timestamp(record_date) < DIVIDEND_RULE_FROM:
        raise ValueError(
            f"record dates before {DIVIDEND_RULE_FROM.date()} predate Caishui [2015] No. 101. "
            f"A differentiated regime applied before it as well, with different inclusion "
            f"fractions; this library has NOT verified that one. Read the circular in force "
            f"for your period rather than extrapolating these rates backwards.")
    return DIVIDEND_EFFECTIVE_RATE[holding_bucket(buy_date, sell_date)]


def dividend_tax(dividend: float, buy_date, sell_date, record_date=None) -> float:
    """Tax withheld on `dividend`. Note the WHEN: 财税〔2015〕101号 defers the withholding to
    the sale, so the cash arrives gross and the tax is taken out of the sale proceeds."""
    return float(dividend) * dividend_tax_rate(buy_date, sell_date, record_date)


# --------------------------------------------------------------------------- cost models
def flat_symmetric_cost(blotter: pd.DataFrame, bps_per_side: float = 10.0) -> float:
    """What most A-share backtests charge: the same bps on every trade, both sides."""
    notional = (blotter["qty"] * blotter["price"]).abs()
    return float((notional * bps_per_side / 1e4).sum())


def real_stamp_duty(blotter: pd.DataFrame, instrument: str = "stock") -> float:
    """The actual tax: seller side only, at the rate in force on each trade's own date."""
    return float(sum(stamp_duty(abs(r.qty * r.price), r.side, r.date, instrument)
                     for r in blotter.itertuples(index=False)))


def compare_cost_models(blotter: pd.DataFrame, bps_per_side: float = 10.0) -> dict:
    notional = float((blotter["qty"] * blotter["price"]).abs().sum())
    sells = blotter["side"].astype(str).str.upper().str[0] == "S"
    sell_notional = float((blotter.loc[sells, "qty"] * blotter.loc[sells, "price"]).abs().sum())
    flat = flat_symmetric_cost(blotter, bps_per_side)
    real = real_stamp_duty(blotter)
    return {"n_trades": int(len(blotter)), "gross_notional": notional,
            "sell_notional": sell_notional, "flat_symmetric": flat, "real_stamp_duty": real,
            "overstatement": flat - real,
            "ratio": flat / real if real else float("inf"),
            "flat_bps_of_notional": 1e4 * flat / notional if notional else 0.0,
            "real_bps_of_notional": 1e4 * real / notional if notional else 0.0}


# --------------------------------------------------------------------------- demo
def make_ashare_path(seed: int = 20260909, start: str = "2021-01-04", years: int = 5,
                     s0: float = 20.0, mu: float = 0.06, sigma: float = 0.30) -> pd.Series:
    """One seeded daily series that spans 2023-08-28, the date the duty halved."""
    rng = np.random.default_rng(seed)
    n = years * 244                                   # ~244 A-share trading days a year
    dates = pd.bdate_range(start, periods=n)
    step = rng.normal(mu / 244.0 - 0.5 * sigma**2 / 244.0, sigma / np.sqrt(244.0), n)
    return pd.Series(s0 * np.exp(np.cumsum(step)), index=dates)


def make_turnover_blotter(px: pd.Series, hold_days: int, shares: float = 100_000.0
                          ) -> pd.DataFrame:
    """Buy `shares`, then round-trip every `hold_days`. hold_days <= 0 means buy and hold."""
    d = px.index
    rows = [{"date": d[0], "side": "B", "qty": shares, "price": float(px.iloc[0])}]
    if hold_days and hold_days > 0:
        for i in range(hold_days, len(px), hold_days):
            p = float(px.iloc[i])
            rows.append({"date": d[i], "side": "S", "qty": shares, "price": p})
            rows.append({"date": d[i], "side": "B", "qty": shares, "price": p})
    return pd.DataFrame(rows)


def dividend_drag(px: pd.Series, hold_days: int, yield_pa: float = 0.025,
                  shares: float = 100_000.0) -> dict:
    """Annual dividend, collected by a strategy that round-trips every `hold_days`.

    The holding period that decides the rate runs from the purchase of the shares that were
    on the register to their sale (FIFO), which is how 中国结算 computes it at the sale.
    """
    blotter = make_turnover_blotter(px, hold_days, shares)
    buys = blotter.loc[blotter["side"] == "B"].reset_index(drop=True)
    sells = blotter.loc[blotter["side"] == "S"].reset_index(drop=True)
    record_dates = [d for d in px.index if d.month == 6 and d.day <= 3][:1] or []
    record_dates = sorted({px.index[px.index.searchsorted(pd.Timestamp(f"{y}-06-15"))]
                           for y in sorted(set(px.index.year))
                           if px.index[0] <= pd.Timestamp(f"{y}-06-15") <= px.index[-1]})
    gross = tax = 0.0
    rows = []
    for rd in record_dates:
        held = buys.loc[buys["date"] <= rd]
        if held.empty:
            continue
        buy_date = held["date"].iloc[-1]
        later = sells.loc[sells["date"] > rd, "date"]
        sell_date = later.iloc[0] if len(later) else px.index[-1]
        div = shares * float(px.loc[rd]) * yield_pa
        r = dividend_tax_rate(buy_date, sell_date, record_date=rd)
        gross += div
        tax += div * r
        rows.append({"record_date": rd, "buy_date": buy_date, "sell_date": sell_date,
                     "bucket": holding_bucket(buy_date, sell_date), "dividend": div,
                     "rate": r, "tax": div * r})
    start_value = shares * float(px.iloc[0])
    years = (px.index[-1] - px.index[0]).days / 365.25
    return {"detail": pd.DataFrame(rows), "gross_dividend": gross, "dividend_tax": tax,
            "effective_rate": tax / gross if gross else 0.0,
            "drag_bps_pa": 1e4 * (tax / start_value) / years if years else 0.0}


def main() -> None:
    print("A-share trading taxes -- seller-side stamp duty, and a dividend tax on turnover")
    print("  stamp duty rate history (verified from 2008-09-19):")
    for _, r in rate_history_table().iterrows():
        print(f"    from {r['from']}   {r['rate']:.4%}  on {r['sides']} only   {r['authority']}")
    print(f"  a BUY pays {stamp_duty(1_000_000, 'B', '2025-01-02'):.2f} on 1,000,000 notional; "
          f"a SELL pays {stamp_duty(1_000_000, 'S', '2025-01-02'):.2f}")
    print(f"  the same SELL on 2023-08-25 paid "
          f"{stamp_duty(1_000_000, 'S', '2023-08-25'):.2f}; on 2023-08-28, "
          f"{stamp_duty(1_000_000, 'S', '2023-08-28'):.2f}")
    print(f"  the same trade in an ETF pays "
          f"{stamp_duty(1_000_000, 'S', '2025-01-02', instrument='etf'):.2f} -- "
          f"Stamp Tax Law art. 3 reaches shares and share-based CDRs, not funds")

    px = make_ashare_path()
    print()
    print(f"  seeded A-share path {px.index[0].date()} to {px.index[-1].date()} "
          f"(spans the 2023-08-28 cut), 100,000 shares")
    print()
    print("  hold(d)  trades   gross notional   flat 10bps/side   real stamp duty   ratio")
    for h in (5, 21, 63, 244, 0):
        c = compare_cost_models(make_turnover_blotter(px, h))
        label = "hold" if not h else str(h)
        ratio = f"{c['ratio']:.1f}x" if np.isfinite(c["ratio"]) else "n/a"
        print(f"  {label:>7}{c['n_trades']:>8}{c['gross_notional']:>17,.0f}"
              f"{c['flat_symmetric']:>18,.0f}{c['real_stamp_duty']:>18,.0f}"
              f"{ratio:>8}")

    b21 = make_turnover_blotter(px, 21)
    c = compare_cost_models(b21)
    print()
    print(f"  monthly rebalance: the flat model charges {c['flat_bps_of_notional']:.1f} bps of "
          f"traded notional, the tax is {c['real_bps_of_notional']:.2f} bps -- "
          f"{c['ratio']:.1f}x too much,")
    print(f"  and it charges the buy side, which pays nothing at all. Overstated by "
          f"{c['overstatement']:,.0f} on {c['gross_notional']:,.0f} of turnover.")

    cut = pd.Timestamp("2023-08-28")
    before, after = b21.loc[b21["date"] < cut], b21.loc[b21["date"] >= cut]
    for name, part in (("before 2023-08-28", before), ("from 2023-08-28", after)):
        cc = compare_cost_models(part)
        print(f"  {name}: {cc['real_stamp_duty']:>10,.0f} of duty on "
              f"{cc['sell_notional']:,.0f} of sells = "
              f"{1e4 * cc['real_stamp_duty'] / cc['sell_notional']:.1f} bps of sell notional")

    print()
    print("  dividend tax by turnover -- 2.5% yield, one annual dividend, same shares:")
    print("  hold(d)   bucket    gross dividend   tax    effective   drag bps/yr")
    for h in (5, 21, 63, 244, 0):
        d = dividend_drag(px, h)
        label = "hold" if not h else str(h)
        bucket = (d["detail"]["bucket"].mode().iloc[0] if len(d["detail"]) else "-")
        print(f"  {label:>7}{bucket:>10}{d['gross_dividend']:>17,.0f}{d['dividend_tax']:>8,.0f}"
              f"{d['effective_rate']:>12.1%}{d['drag_bps_pa']:>14.1f}")

    print()
    print("  the boundary is one day wide (Caishui [2015] No. 101 -- one month AND one year "
          "are inclusive):")
    for b, s in (("2024-01-10", "2024-02-10"), ("2024-01-10", "2024-02-11"),
                 ("2024-01-10", "2025-01-10"), ("2024-01-10", "2025-01-11")):
        print(f"    bought {b}, sold {s} -> {holding_bucket(b, s):>6}  "
              f"{dividend_tax_rate(b, s):.0%}")

    print()
    print("RULE: A-share stamp duty is seller-side only and halved to 0.05% on 2023-08-28, "
          "and dividend tax is 20/10/0 by holding period -- a turnover penalty in the tax code.")


if __name__ == "__main__":
    main()
